:root {
  /* Kid-friendly background palette (soft, warm, no harsh contrast) */
  --kids-bg: #fff8f0;
  --kids-bg-2: #f3fbff;
  --kids-bg-3: #fff1fb;

  --kids-panel: rgba(255, 255, 255, 0.92);
  --kids-shadow: rgba(0, 0, 0, 0.12);
  --kids-stroke: rgba(0, 0, 0, 0.08);

  --kids-accent: rgba(255, 107, 107, 0.22);
  --kids-accent-strong: rgba(255, 107, 107, 0.38);

  --kids-text: rgba(0, 0, 0, 0.82);
  --kids-muted: rgba(0, 0, 0, 0.52);
}

.App {
  min-height: 100vh;

  /* Soft gradient + subtle pattern (static, no animation) */
  background:
    radial-gradient(circle at 10% 10%, rgba(255, 193, 7, 0.14), transparent 42%),
    radial-gradient(circle at 90% 15%, rgba(255, 107, 107, 0.12), transparent 44%),
    radial-gradient(circle at 20% 90%, rgba(76, 175, 80, 0.10), transparent 46%),
    radial-gradient(circle at 85% 85%, rgba(33, 150, 243, 0.10), transparent 46%),
    repeating-linear-gradient(
      45deg,
      rgba(0, 0, 0, 0.015) 0px,
      rgba(0, 0, 0, 0.015) 10px,
      transparent 10px,
      transparent 20px
    ),
    linear-gradient(135deg, var(--kids-bg), var(--kids-bg-2) 55%, var(--kids-bg-3));

  color: var(--kids-text);
  overflow: hidden;
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
}

/* Force landscape view on mobile/portrait */
@media screen and (orientation: portrait) {
  .App {
    width: 100vh;
    height: 100vw;
    transform: rotate(90deg);
    transform-origin: bottom left;
    position: absolute;
    top: -100vw;
    left: 0;
  }
}

.KidsTopBar {
  position: sticky;
  top: 0;
  z-index: 10;

  display: flex;
  align-items: center;
  gap: 10px;

  /* Fixed height so the scene can reliably take full viewport below it */
  height: 72px;
  padding: 10px 12px;
  box-sizing: border-box;

  background: var(--kids-panel);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--kids-stroke);
}

.KidsTopBarSpacer {
  flex: 1;
}

.KidsButton {
  appearance: none;
  border: 1px solid var(--kids-stroke);
  background: white;
  color: var(--kids-text);
  border-radius: 14px;
  padding: 12px 14px;

  font-size: 16px;
  font-weight: 700;

  box-shadow: 0 6px 18px var(--kids-shadow);
}

.KidsButton:disabled {
  opacity: 0.55;
  box-shadow: none;
}

.KidsLangSwitch {
  display: inline-flex;
  background: rgba(0, 0, 0, 0.04);
  border: 1px solid var(--kids-stroke);
  border-radius: 14px;
  overflow: hidden;
}

.KidsLangButton {
  appearance: none;
  border: 0;
  background: transparent;
  padding: 12px 14px;

  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.5px;

  color: var(--kids-muted);
}

.KidsLangButton.isActive {
  background: white;
  color: var(--kids-text);
}

.KidsMain {
  /* Fullscreen scene uses its own layout; do not add padding around it */
  padding: 0;
}

.KidsLoading {
  text-align: center;
  padding: 18px 12px;
  font-weight: 700;
  color: var(--kids-muted);
}

.KidsStoryStage {
  position: relative;
  flex: 1;
  height: 0; /* Let flex-grow handle it */
}

.KidsSceneWrap {
  position: relative;
  width: 100vw;
  height: 100%;
  max-width: none;
  margin: 0;

  border-radius: 0;
  overflow: hidden;
  border: 0;
  box-shadow: none;
  background: white;
}

.KidsSceneImage {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;

  user-select: none;
  -webkit-user-select: none;
}

.KidsZonesLayer {
  position: absolute;
  inset: 0;
}

.KidsZone {
  position: absolute;
  border: 2px solid rgba(255, 107, 107, 0.28);
  background: rgba(255, 107, 107, 0.14);
  box-shadow: 0 10px 24px rgba(255, 107, 107, 0.12);

  touch-action: manipulation;
}

@media (hover: hover) and (pointer: fine) {
  .KidsZone:hover {
    transform: translate(-50%, -50%) scale(1.06);
    border-color: rgba(255, 193, 7, 0.55);
    box-shadow: 0 12px 30px rgba(255, 193, 7, 0.18);
  }
}

.KidsZone:active {
  background: rgba(255, 107, 107, 0.22);
  border-color: rgba(255, 107, 107, 0.46);
}

.KidsSceneNav {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 12px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;

  pointer-events: none;
}

.KidsSceneNav > * {
  pointer-events: auto;
}

.KidsNavButton {
  appearance: none;
  border: 1px solid var(--kids-stroke);
  background: white;
  border-radius: 16px;
  width: 64px;
  height: 54px;
  font-size: 26px;
  font-weight: 900;
  color: var(--kids-text);
  box-shadow: 0 8px 22px var(--kids-shadow);
}

.KidsNavButton:disabled {
  opacity: 0.35;
  box-shadow: none;
}

.KidsSceneDots {
  display: inline-flex;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.04);
  border: 1px solid var(--kids-stroke);
}

.KidsDot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.18);
}

.KidsDot.isActive {
  background: var(--kids-accent-strong);
}

.KidsCurrentStory {
  position: fixed;
  left: 12px;
  bottom: 12px;
  z-index: 11;

  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--kids-stroke);
  color: var(--kids-muted);
  font-weight: 700;
  max-width: calc(100vw - 24px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Overlay: story picker */
.KidsOverlay {
  position: fixed;
  inset: 0;
  z-index: 100;

  /* Keep readability but feel "kid-friendly" */
  background:
    radial-gradient(circle at 20% 10%, rgba(255, 193, 7, 0.22), transparent 45%),
    radial-gradient(circle at 80% 20%, rgba(255, 107, 107, 0.18), transparent 48%),
    radial-gradient(circle at 30% 85%, rgba(33, 150, 243, 0.16), transparent 52%),
    rgba(0, 0, 0, 0.18);

  backdrop-filter: blur(6px);

  display: flex;
  flex-direction: column;
  padding: 14px;
}

.KidsOverlayHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  padding: 12px 12px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid var(--kids-stroke);
  box-shadow: 0 10px 28px var(--kids-shadow);
}

.KidsOverlayTitle {
  font-size: 18px;
  font-weight: 900;
}

.KidsStoryGrid {
  margin-top: 14px;
  flex: 1;

  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

@media (min-width: 768px) {
  .KidsStoryGrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.KidsStoryCard {
  appearance: none;
  border: 1px solid var(--kids-stroke);
  background: rgba(255, 255, 255, 0.94);
  border-radius: 20px;
  padding: 12px;

  display: grid;
  gap: 10px;
  align-content: start;

  box-shadow: 0 12px 30px var(--kids-shadow);
}

.KidsStoryCardImageWrap {
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--kids-stroke);
}

.KidsStoryCardImage {
  width: 100%;
  height: auto;
  display: block;
  user-select: none;
  -webkit-user-select: none;
}

.KidsStoryCardTitle {
  font-weight: 900;
  font-size: 16px;
}

.KidsStoryCardBadge {
  display: inline-block;
  padding: 6px 10px;
  border-radius: 999px;
  font-weight: 900;
  font-size: 12px;
  color: rgba(0, 0, 0, 0.62);
  background: var(--kids-accent);
  justify-self: start;
}

/* Safety: reduce motion */
@media (prefers-reduced-motion: reduce) {
  .KidsZone,
  .KidsNavButton,
  .KidsButton,
  .KidsStoryCard {
    transition: none !important;
  }
}
